import React, { useEffect, useState } from 'react';
import axios from 'axios';

function Admin() {
  const [users, setUsers] = useState([]);
  const [scans, setScans] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchUsers = async () => {
    setError(null);
    setLoading(true);
    try {
      const res = await axios.get('/api/auth/admin/users');
      setUsers(res.data.users || []);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const fetchScans = async () => {
    setError(null);
    setLoading(true);
    try {
      const res = await axios.get('/api/malware/history');
      setScans(res.data.history || []);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to load scan history');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchScans();
  }, []);

  return (
    <div>
      <h2>Admin Panel</h2>
      {error && <div className="alert alert-danger">{error}</div>}
      <div className="row">
        <div className="col-md-6">
          <div className="card bg-dark text-white mb-3">
            <div className="card-body">
              <h5 className="card-title">Users</h5>
              {loading ? (
                <p>Loading...</p>
              ) : (
                <table className="table table-sm table-dark table-striped">
                  <thead>
                    <tr>
                      <th>Username</th>
                      <th>Role</th>
                      <th>Tenant</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.map((u) => (
                      <tr key={u.id}>
                        <td>{u.username}</td>
                        <td>{u.role}</td>
                        <td>{u.tenant_id}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>

        <div className="col-md-6">
          <div className="card bg-dark text-white mb-3">
            <div className="card-body">
              <h5 className="card-title">Recent Scans</h5>
              {loading ? (
                <p>Loading...</p>
              ) : (
                <table className="table table-sm table-dark table-striped">
                  <thead>
                    <tr>
                      <th>File</th>
                      <th>Status</th>
                      <th>Scanned At</th>
                    </tr>
                  </thead>
                  <tbody>
                    {scans.map((s) => (
                      <tr key={s.id}>
                        <td>{s.filename}</td>
                        <td>{s.status}</td>
                        <td>{new Date(s.scanned_at).toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Admin;
